import raw from '../data/campus.json'
import polygonClipping from 'polygon-clipping'
import { BUILDINGS } from '../data/buildings'
import type { BuildingInfo, Vec2 } from '../types'
import { centroid, pointInPolygon, toLocal } from './geo'
import { walkwayOutlines } from './architecture'

// campus.json is generated by scripts/fetch-osm.mjs, which tags every feature with a `layer`.
type Layer = 'building' | 'path' | 'road' | 'campus' | 'green' | 'pitch' | 'water' | 'tree'

interface Feature {
  properties: Record<string, string | undefined> & { layer: Layer }
  geometry: { type: string; coordinates: unknown }
}

export interface CampusBuilding {
  osmId: string
  ring: Vec2[]
  center: Vec2
  levels: number
  /** Explicit OSM height, where available, in metres. */
  heightMeters?: number
  /** Inside the university grounds, or listed in data/buildings.ts. */
  onCampus: boolean
  /** Present only for buildings listed in data/buildings.ts. */
  info?: BuildingInfo
  name?: string
}

export interface CampusArea {
  kind: 'green' | 'pitch' | 'water'
  ring: Vec2[]
  osmId: string
  name?: string
  sport?: string
  surface?: string
}

export interface CampusWalkway { osmId: string; line: Vec2[]; bridge: boolean; width: number; mappedWidth?: number }

const features = (raw as unknown as { features: Feature[] }).features
const inLayer = (layer: Layer) => features.filter((f) => f.properties.layer === layer)
// Outer ring only: courtyards are ignored at this level of detail.
const ringOf = (f: Feature) => (f.geometry.coordinates as number[][][])[0].map(toLocal)
const lineOf = (f: Feature) => (f.geometry.coordinates as number[][]).map(toLocal)

const infoByOsmId = new Map(BUILDINGS.map((b) => [b.osmId, b]))

const mappedCampusBoundary: Vec2[] = inLayer('campus').map(ringOf)[0] ?? []

const mainBridge = lineOf(inLayer('path').find(f => f.properties.osm_id === 'way/390625920')!)
const bridgeCorner = mainBridge.at(-1)!
// The south frontage is the campus edge; the street ramp lies outside it.
const southCorner = mappedCampusBoundary.findIndex(([, y]) => y < -165)
export const CAMPUS_BOUNDARY: Vec2[] = [
  ...mappedCampusBoundary.slice(0, southCorner),
  [21.64, -166.7], [-3.1, -155.8], bridgeCorner, [-5.7, -152.9],
  [-15.2, -150.2], [-28.3, -148.8], [-29, -145.5], [-41.5, -145.45],
  ...mappedCampusBoundary.slice(southCorner + 2),
]
/** Student-confirmed connection from the inter-court passage to the bridge corner. */
export const CAMPUS_BRIDGE_ACCESS: CampusWalkway = {
  osmId: 'campus/bridge-access', line: [bridgeCorner, [-3.2, -152.5], [-2.8, -141]], bridge: false, width: 2.8,
}
const bridgeBefore = mainBridge.at(-2)!, bridgeRun = Math.hypot(bridgeBefore[0] - bridgeCorner[0], bridgeBefore[1] - bridgeCorner[1])
export const CAMPUS_BRIDGE_ACCESS_OUTLINES = [
  ...walkwayOutlines([[bridgeCorner[0] + (bridgeBefore[0] - bridgeCorner[0]) * 5 / bridgeRun, bridgeCorner[1] + (bridgeBefore[1] - bridgeCorner[1]) * 5 / bridgeRun], ...CAMPUS_BRIDGE_ACCESS.line], 2.8),
]
export const CAMPUS_STREET_ACCESS = lineOf(inLayer('path').find(f => f.properties.osm_id === 'way/1032704765')!)
export const CAMPUS_STREET_CUTOUTS = [
  ...walkwayOutlines(lineOf(inLayer('path').find(f => f.properties.osm_id === 'way/1032704764')!), 3.2),
  ...walkwayOutlines(CAMPUS_STREET_ACCESS, 3.2),
  Array.from({ length: 16 }, (_, i): Vec2 => {
    const p = CAMPUS_STREET_ACCESS.at(-1)!
    return [p[0] + Math.cos(i * Math.PI / 8) * 1.8, p[1] + Math.sin(i * Math.PI / 8) * 1.8]
  }),
]

// The student's photo shows an exterior gap that OSM's touching outlines omit.
// Preserve the Hall completely. The exterior gap ends at the covered ramp tunnel;
// behind that mouth, both original building outlines join again.
export const HALL_EINSTEIN_GAP = 3.8
export const HALL_EINSTEIN_OPEN_LENGTH = 14
const hallRing = ringOf(inLayer('building').find(f=>f.properties.osm_id==='way/395847792')!)
const hallStart = hallRing.at(-3)!, hallEnd = hallRing.at(-2)!
const hallWidth = Math.hypot(hallEnd[0]-hallStart[0],hallEnd[1]-hallStart[1])
const hallUx = (hallEnd[0]-hallStart[0])/hallWidth, hallUy = (hallEnd[1]-hallStart[1])/hallWidth
const einsteinFrontGap:Vec2[] = ([[-1,.15],[HALL_EINSTEIN_GAP,.15],[HALL_EINSTEIN_GAP,-HALL_EINSTEIN_OPEN_LENGTH],[-1,-HALL_EINSTEIN_OPEN_LENGTH]] as Vec2[]).map(([x,z])=>[hallEnd[0]+hallUx*x+hallUy*z,hallEnd[1]+hallUy*x-hallUx*z])

// Student's photos put the small annex on the raised garden, clear of the lane
// and the Obelisk. Apply the visual correction here so rendering, clipping,
// route endpoints and animal obstacles share the same footprint.
export const SPORTS_ANNEX_OFFSET: Vec2 = [-4.4, 6]

export const CAMPUS_BUILDINGS: CampusBuilding[] = inLayer('building').map((f) => {
  const original = ringOf(f)
  const ring = f.properties.osm_id === 'way/1036855377' ? polygonClipping.difference([original], ...CAMPUS_BRIDGE_ACCESS_OUTLINES.map(r => [r]))[0][0] as Vec2[] : f.properties.osm_id === 'way/395847790' ? polygonClipping.difference([original],[einsteinFrontGap])[0][0] as Vec2[] : f.properties.osm_id === 'way/395853835' ? original.map(([x,y]):Vec2 => [x + SPORTS_ANNEX_OFFSET[0], y + SPORTS_ANNEX_OFFSET[1]]) : original
  const center = centroid(ring)
  const osmId = f.properties.osm_id ?? ''
  const info = infoByOsmId.get(osmId)
  return {
    osmId,
    ring,
    center,
    levels: info?.id === 'gobe' ? 2 : Number(f.properties['building:levels']) || 1,
    heightMeters: info?.id === 'gobe' ? 6.4 : Number.parseFloat(f.properties.height ?? '') > 0 ? Number.parseFloat(f.properties.height!) : undefined,
    onCampus: !!info || pointInPolygon(center, CAMPUS_BOUNDARY),
    info,
    name: info?.name ?? f.properties.name,
  }
})

/** Walkways and service lanes: what outdoor routes are allowed to follow. */
export const CAMPUS_WALKWAYS: CampusWalkway[] = inLayer('path').map((f) => ({
  osmId: f.properties.osm_id ?? '', line: lineOf(f), bridge: !!f.properties.bridge && f.properties.bridge !== 'no', width: Number(f.properties.width) || 2.6, mappedWidth: Number(f.properties.width) || undefined,
}))
export const CAMPUS_PATHS: Vec2[][] = [...CAMPUS_WALKWAYS, CAMPUS_BRIDGE_ACCESS].map((path) => path.line)

/** City streets around the campus. Drawn for context, never routed over. */
export const CITY_ROADS: { line: Vec2[]; major: boolean }[] = inLayer('road').map((f) => ({
  line: lineOf(f),
  major: /^(primary|secondary|tertiary)/.test(f.properties.highway ?? ''),
}))

export const CAMPUS_AREAS: CampusArea[] = (['green', 'pitch', 'water'] as const).flatMap((kind) =>
  inLayer(kind).map((f) => ({ kind, ring: ringOf(f), osmId: f.properties.osm_id ?? '', name: f.properties.name, sport: f.properties.sport, surface: f.properties.surface })),
)

export const CAMPUS_TREES: Vec2[] = inLayer('tree').map((f) => toLocal(f.geometry.coordinates as number[]))

export function findCampusBuilding(buildingId: string): CampusBuilding | undefined {
  return CAMPUS_BUILDINGS.find((b) => b.info?.id === buildingId)
}
